      "userRequirements": "Provide aria-label or wrap in FormField"
    },
    {
      "feature": "Progress",
      "implementation": "Each uploading file exposes role=progressbar with a name",
      "userRequirements": "Keep progress keyed by file name"
    }
  ],
  "contentGuidelines": [
    {
      "contentType": "Hints",
