        "State accepted types and size limits"
      ],
      "goodExamples": [
        "PDF or CSV, up to 10 MB"
      ],
      "badExamples": [
        "Upload"
      ]
    }
  ],
  "compositionRules": [
    {
      "component": "FormField",
      "relationship": "Wrap for label/error wiring",
      "example": "<FormField id=\"files\" label=\"Attachments\"><FileUpload /></FormField>"
    }
  ],
  "relatedComponents": [
    "Attachment",
    "FormField",
    "Progress"
  ],
  "package": "@slipstream-ui/core",
  "importPath": "@slipstream-ui/core",
  "version": "0.8.0",
  "sourceDir": "file-upload",
  "exportName": "FileUpload"
}
